export function CompositeComponent({
  name = "{{name}}",
  childCount = "{{childCount}}",
  accent = "{{accent}}",
  showLabels = {{showLabels}},
}) {
  const n = Number(childCount);
  const children = [0, 1, 2].filter((i) => i < n);
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box", border: "1.5px dashed #24143030" }}>
      <p style={{ margin: 0, fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>&lt;{name}&gt;</p>
      <div style={{ display: "flex", gap: 8, minHeight: 34, padding: "8px 0" }}>
        {children.map((i) => (
          <div key={i} style={{ flex: 1, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 600, background: accent }}>
            {showLabels && "Button"}
          </div>
        ))}
      </div>
      <p style={{ margin: 0, fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>&lt;/{name}&gt;</p>
    </div>
  );
}
